/* Phase 3 reuses Account's same-origin requests, session, cache and serialized actions. */
window.Organization=(()=>{
  const e=value=>escapeHTML(value??'');
  const A=()=>Account;
  const path=()=> (location.hash.slice(1)||'/').split('?')[0];
  const params=()=>new URLSearchParams(location.hash.split('?')[1]||'');
  const labels={draft:'Draft',onboarding:'Setup in progress',pending_review:'Pending activation review',active:'Active',suspended:'Suspended',not_requested:'Not requested',pending:'Pending marketplace review',approved:'Approved · not business verification',rejected:'Changes requested',withdrawn:'Withdrawn'};
  const serviceLabels={solar_panels:'Solar panels',inverters:'Inverters',batteries:'Batteries',rooftop_installation:'Rooftop installation',maintenance:'Maintenance',energy_consultation:'Energy consultation'};
  let defaults=null;
  let invitationToken='',invitationKind='employee',invitationReceipt=null,invitationPreview=null,invitationPreviewError='',previewScope='',logoHosts=[];
  function captureInvitation(){if(path()==='/invitation'&&params().has('token')){invitationPreview=null;invitationPreviewError='';previewScope='';invitationToken=params().get('token');invitationKind=['customer','partner'].includes(params().get('kind'))?params().get('kind'):'employee';window.history.replaceState(null,'',`${location.pathname}${location.search}#/invitation`);}}
  captureInvitation();window.addEventListener('hashchange',captureInvitation);
  const when=value=>new Date(value).toLocaleString(locale==='ml'?'ml-IN':locale==='ta'?'ta-IN':'en-IN',{timeZone:'Asia/Kolkata'});
  const chip=(value)=>status(e(labels[value]||value),['active','approved'].includes(value)?'blue':['suspended','rejected'].includes(value)?'neutral':'gold');
  const field=(label,name,value='',extra='',type='text')=>A().field(label,name,type,value,extra);
  function select(label,name,choices,value){return `<label>${label}<select name="${name}">${choices.map(([key,title,disabled=false])=>`<option value="${e(key)}" ${key===value?'selected':''} ${disabled?'disabled':''}>${e(title)}</option>`).join('')}</select></label>`;}
  function checkbox(label,name,checked){return `<label class="checkbox-label"><input type="checkbox" name="${name}" ${checked?'checked':''}>${label}</label>`;}
  function textarea(label,name,value,extra=''){return `<label>${label}<textarea name="${name}" rows="3" ${extra}>${e(value)}</textarea></label>`;}
  function revision(c){return `<input type="hidden" name="revision" value="${c.revision}">`;}
  function orgForm(id,content,cta){return `<form id="${id}" class="org-form">${content}<p class="org-feedback account-feedback" role="status" aria-live="polite"></p><button class="btn primary" type="submit">${cta}${icon('arrow')}</button></form>`;}
  function logo(url){return `<span class="org-logo">${url?`<img class="tenant-logo" src="${e(url)}" alt="" referrerpolicy="no-referrer">`:''}<span class="logo-fallback">${icon('sun')}</span></span>`;}
  function history(items){return `<section class="panel account-space"><div class="panel-heading"><h2>Review and company activity</h2></div><ul class="review-list">${items.map(item=>`<li><div><strong>${e(item.kind||item.action)}</strong><span>${e(item.operator||'Company event')} · ${e(when(item.created_at))}</span></div>${item.previous_state?`<p>${e(labels[item.previous_state]||item.previous_state)} ${icon('arrow')} ${e(labels[item.new_state]||item.new_state)}</p>`:''}${item.reason?`<p class="muted">${e(item.reason)}</p>`:''}</li>`).join('')||'<li>No review events yet.</li>'}</ul></section>`;}
  function ownerNav(){return `<nav class="org-subnav" aria-label="Company setup">${[['/distributor/dashboard','Today'],['/distributor/setup','Company setup'],['/distributor/team','Team']].filter(([url])=>A().navAllowed(url)).map(([url,label])=>link(url,label)).join('')}</nav>`;}
  function setupProgress(d){const steps=[['profile',d.onboarding.profile_saved_at,'Company details'],['brand',d.onboarding.brand_saved_at,'Public identity'],['business',d.onboarding.business_saved_at,'Services & coverage']];return link('/distributor/setup?step=guide','Open complete setup guide '+icon('arrow'),'btn primary')+link('/distributor/setup?step=delivery','Onboarding & delivery checks','btn secondary')+'<ol class="setup-progress">'+steps.map(([step,done,label])=>'<li class="'+(done?'saved':'')+'">'+link('/distributor/setup?step='+step,'<span>'+icon(done?'check':'arrow')+'</span><strong>'+label+'</strong><small>'+(done?'Saved':'To do')+'</small>')+'</li>').join('')+'</ol>'+link('/distributor/setup?step=review','Review setup & activation status','btn secondary');}
  function summary(d){const c=d.company;return heading('YOUR COMPANY WORKSPACE',e(c.name),'Finish your saved setup, then start your working day.',link('/companies','Switch company','btn secondary'))+Workspace.osOverview(d)+Workspace.journey(3)+A().feedback()+Workspace.activation(d)+Workspace.facilities(c)+setupProgress(d)+'<details class="panel workspace-start"><summary>Company review history</summary>'+history(d.history)+'</details>';}
  function facilityPage(p){return A().resource(p,'/companies/current/setup',d=>{
    const c=d.company;if(p==='/distributor/white-label')return heading('YOUR BRANDED PLATFORM','A platform with your identity.','Discuss scope and commercial terms before any setup or domain connection.')+ownerNav()+'<section class="panel settings-panel"><h2>Request a consultation</h2><p>Tell the MY Solar Solutions team about your company branding, landing page and domain needs. This is an enquiry, not a purchase or an activated feature.</p>'+Workspace.consultation(c)+ReleaseTools.consultation()+link('/distributor/website','Prepare your branded page','btn secondary')+'</section>';
    return heading('MY PUBLIC PROFILE',e(d.brand.public_name),'Prepare your marketplace presence. Public listing is separate from your internal workspace.')+ownerNav()+Workspace.facilities(c)+'<section class="panel settings-panel"><h2>Prepare your listing</h2><p>Save your public contact details, description and genuine service coverage. Offers have their own publication rules.</p><div class="account-actions">'+link('/distributor/branding','Edit public identity','btn secondary')+(A().navAllowed('/distributor/service-areas')?link('/distributor/service-areas','Manage service areas','btn secondary'):'')+(A().navAllowed('/distributor/offers')?link('/distributor/offers','Manage offers','btn secondary'):'')+(c.storefront_published?link('/storefront?company='+c.id,'View published profile','btn secondary'):'')+'</div></section>'+reviewStep(d);
  });}
  function profileStep(d){const c=d.company,p=d.profile;return `<section class="panel settings-panel step-panel"><p class="eyebrow">COMPANY DETAILS</p><h2>Tell us about your company.</h2><p class="muted">Your legal identity and private business contact details.</p>${orgForm('org-profile',revision(c)+field('Legal or registered business name','legalName',p.legal_name,'required maxlength="150" autocomplete="organization"')+field('Workspace display name','displayName',c.name,'required maxlength="100"')+Workspace.presetChoices(p.business_preset||p.business_type)+field('Primary contact person','contactPerson',p.primary_contact,'required maxlength="100" autocomplete="name"')+`<div class="form-row">${field('Business email','email',c.business_email,'required maxlength="254"','email')}${field('Business phone','phone',c.phone,'required maxlength="24"','tel')}</div>`+field('Business address','address',p.address,'required maxlength="300" autocomplete="street-address"')+CompanyLocation.fields(p)+field('PIN code','pin',p.pin_code,'required pattern="[1-9][0-9]{5}" maxlength="6" inputmode="numeric" autocomplete="postal-code"')+select('Operating language','language',[['en','English'],['ml','മലയാളം'],['ta','தமிழ்']],p.language)+'<details class="workspace-optional"><summary>Website · optional</summary>'+field('Website · optional HTTPS URL','website',p.website,'maxlength="500" placeholder="https://your-company.example"','url')+'</details>','Save and continue')}</section>`;}
  function brandPreview(b){return `<section id="brand-live-preview" class="brand-live-preview ${b.appearance==='clean'?'clean':''}" style="--preview-primary:${e(b.primary_color)};--preview-secondary:${e(b.secondary_color)};--preview-accent:${e(b.accent_color)}"><span class="pill">PRIVATE THEME PREVIEW</span><div id="preview-logo">${logo(b.logo_url)}</div><p class="eyebrow">YOUR COMPANY STOREFRONT</p><h2 id="preview-name">${e(b.public_name)}</h2><p id="preview-welcome">${e(b.welcome_text)}</p><p id="preview-description">${e(b.description)}</p><span class="preview-cta">Your company. A brighter outlook. ${icon('arrow')}</span><div class="preview-contact"><span id="preview-email">${e(b.public_email)}</span><span id="preview-phone">${e(b.public_phone)}</span></div><small>Visual preview only · Not a live offer or publication</small></section>`;}
  function brandStep(d){logoHosts=d.logoHosts;defaults=d.defaults;const c=d.company,b=d.brand;return `<div class="org-brand-grid"><section class="panel settings-panel"><p class="eyebrow">PUBLIC PROFILE</p><h2>Make it feel like your company.</h2><p class="muted">Preview before saving. Changes to published information remove publication until renewed platform review.</p>${orgForm('org-brand',revision(c)+`<input type="hidden" name="defaultName" value="${e(c.name)}">`+field('Public-facing company name','publicName',b.public_name,'required maxlength="100"')+'<details class="workspace-optional"><summary>Logo and colours · optional</summary>'+field('Logo URL · optional HTTPS PNG, JPEG or WebP','logoUrl',b.logo_url,'maxlength="500"','url')+`<p class="fine-print">${logoHosts.length?'Allowed hosts: '+e(logoHosts.join(', ')):'No external logo hosts configured. Leave blank for the sun mark.'} No file upload or image storage is configured.</p><div class="form-row">${field('Primary colour','primary',b.primary_color,'required','color')}${field('Secondary colour','secondary',b.secondary_color,'required','color')}${field('Accent colour','accent',b.accent_color,'','color')}</div><p class="fine-print">Use dark primary and secondary colours for readable white text. Accent is optional; the default is solar gold.</p>`+'</details>'+field('Storefront welcome text','welcome',b.welcome_text,'maxlength="200"')+`<div class="form-row">${field('Public contact email · optional','email',b.public_email,'maxlength="254"','email')}${field('Public contact phone · optional','phone',b.public_phone,'maxlength="24"','tel')}</div>`+textarea('Basic company description','description',b.description,'required maxlength="500"')+select('Storefront appearance','appearance',[['warm','Warm neutral'],['clean','Clean white']],b.appearance)+field('Future custom domain · optional','requestedDomain',b.requested_domain,'maxlength="253" placeholder="solar.your-company.example"')+`<p class="fine-print">Domain status: not connected. This stores your preference only; it does not provision or verify DNS.</p><button type="button" class="btn secondary" data-org-action="reset-brand">Reset to defaults</button>`,'Save brand')}<p class="fine-print">Reset changes the preview first. Save to persist it for this company.</p></section><aside class="brand-preview-column">${brandPreview(b)}</aside></div>`;}
  function businessStep(d){const c=d.company,b=Workspace.businessDefaults(d);return `<section class="panel settings-panel step-panel"><p class="eyebrow">SERVICES & COVERAGE</p><h2>Choose your services and coverage.</h2><p class="muted">Your business type suggests a starting point. Check the services and areas before saving.</p>${orgForm('org-business',revision(c)+`<fieldset class="service-options"><legend>Products and services offered</legend>${Object.entries(serviceLabels).map(([value,label])=>`<label class="checkbox-label"><input type="checkbox" name="services" value="${value}" ${b.services.includes(value)?'checked':''}>${label}</label>`).join('')}</fieldset>`+checkbox('Rooftop solar installation available','rooftop',b.rooftop_available)+textarea('Service areas · one district or locality per line','areas',b.service_areas.join('\n'),'required maxlength="2020"')+select('Preferred customer contact method','contactMethod',[['email','Email'],['phone','Phone']],b.preferred_contact)+checkbox('Request inclusion in the common MY SOLAR marketplace','marketplaceRequested',b.marketplace_requested)+`<p class="fine-print">This records your interest. Activation, marketplace approval and publication require separate platform decisions.</p>`,'Save and continue')}</section>`;}
  function reviewStep(d){const c=d.company;const complete=d.onboarding.profile_saved_at&&d.onboarding.brand_saved_at&&d.onboarding.business_saved_at;
    return `<section class="panel review-summary"><p class="eyebrow">ACTIVATION REVIEW</p><h2>A clear picture before your next step.</h2><div class="org-status-strip"><div><small>Company</small>${chip(c.lifecycle)}</div><div><small>Marketplace</small>${chip(c.marketplace_status)}</div></div><div class="review-sections"><section><h3>Company profile ${link('/distributor/setup?step=profile','Edit','text-link')}</h3><dl><dt>Legal name</dt><dd>${e(d.profile.legal_name)}</dd><dt>Display name</dt><dd>${e(c.name)}</dd><dt>Business contact</dt><dd>${e(c.business_email)} · ${e(c.phone)}</dd><dt>Location</dt><dd>${e(d.profile.address)}, ${e(d.profile.district)}, ${e(d.profile.state)} ${e(d.profile.pin_code)}</dd></dl></section><section><h3>Brand identity ${link('/distributor/branding','Edit','text-link')}</h3><p>${e(d.brand.public_name)}</p><p class="muted">${e(d.brand.description)||'No description saved.'}</p><p class="muted">Public contact: ${e(d.brand.public_email||d.brand.public_phone)||'Not configured'}</p></section><section><h3>Business profile ${link('/distributor/setup?step=business','Edit','text-link')}</h3><p>${d.business.services.map(value=>e(serviceLabels[value]||value)).join(', ')||'No services saved.'}</p><p class="muted">${e(d.business.service_areas.join(', '))||'No service areas saved.'}</p><p class="muted">Marketplace interest: ${d.business.marketplace_requested?'Requested':'Not requested'}</p></section></div>${A().feedback()}<p class="org-feedback account-feedback" role="status"></p>${c.lifecycle==='pending_review'?`<p class="muted">A platform operator will review your company. Withdraw the submission if you need to edit.</p><button class="btn secondary" data-org-action="withdraw" data-revision="${c.revision}">Withdraw to edit</button>`:c.lifecycle==='active'?`<p class="muted">Your company is active. Marketplace inclusion remains a separate decision.</p><div class="account-actions">${!['pending','approved'].includes(c.marketplace_status)?`<button class="btn primary" data-org-action="market-request" data-revision="${c.revision}">Request marketplace review</button>`:`<button class="btn secondary" data-org-action="market-withdraw" data-revision="${c.revision}">Withdraw marketplace inclusion</button>`}${c.storefront_published?link(`/storefront?company=${c.id}`,'Open public storefront','btn secondary'):''}</div>`:c.lifecycle==='suspended'?'<p class="muted">This company is suspended. Contact a platform operator; self-reactivation is unavailable.</p>':`<button class="btn primary" data-org-action="submit" data-revision="${c.revision}" ${complete?'':'disabled'}>Submit for activation review ${icon('arrow')}</button><p class="fine-print">Save all three setup steps first. Submission does not verify, activate or publish the company.</p>`}</section>${history(d.history)}`;
  }
  function deliveryPage(p){return A().resource(p,'/companies/current/setup/delivery',d=>heading('CONTROLLED ONBOARDING & DELIVERY','Know what is ready.','Saved company evidence and explicit external acceptance gates.')+ownerNav()+A().feedback()+'<section class="panel settings-panel"><h2>'+e(d.decision)+'</h2><p>'+e(d.notice)+'</p><p>Setup: '+d.setup.completed+' of '+d.setup.total+' steps reviewed. Access mode: '+e(d.access.mode)+'. Subscription status: '+e(d.access.status)+'.</p>'+(d.access.subscription?'<p>Assigned plan: '+e(d.access.subscription.name)+' ('+e(d.access.subscription.code)+'). Recorded dates do not prove payment.</p>':'<p>No assigned plan is shown. Review the configured access mode with the platform administrator.</p>')+'<div class="account-actions">'+link('/distributor/setup?step=guide','Continue setup','btn primary')+(A().navAllowed('/distributor/subscription')?link('/distributor/subscription','Plan & entitlements','btn secondary'):'')+link('/distributor/white-label','Branded platform consultation','btn secondary')+'</div></section><ol class="practical-setup-steps">'+d.gates.map(g=>'<li class="panel"><h2>'+e(g.label)+'</h2><p>'+e(g.state)+'</p></li>').join('')+'</ol><section class="panel settings-panel"><h2>Share your public business page</h2>'+(d.publicProfile.published?'<p>This current public profile is eligible for marketplace discovery.</p><label>Public company page<input type="url" readonly value="'+e(d.publicProfile.url)+'" aria-label="Public company page to copy"></label><a class="btn secondary" href="'+e(d.publicProfile.url)+'">Open published profile</a>':'<p>Your business does not currently have an eligible published profile. Complete the listing and its independent review before sharing it as available.</p>')+'<p>Domain ownership verification, HTTPS and production activation remain separate. No custom-domain purchase or configuration happens here.</p><a class="btn secondary" href="tel:'+e(d.support.phone)+'">Call platform support</a></section>');}
  function practicalSetup(p){return A().resource(p,'/companies/current/setup/guide',({company:c,guide:g})=>{
   const states={saved:'Saved records',not_needed:'Owner chose not needed',reviewed:'Owner reviewed',pending:'Awaiting acceptance',later:'Deferred',todo:'To do'};
   const destination=(url,label)=>A().navAllowed(url.split('?')[0])?link(url,label+' '+icon('arrow'),'btn secondary'):'<p class="fine-print">Available after company activation and with the required access.</p>';
   return heading('PRACTICAL COMPANY SETUP','Get your business ready.','Work through these steps at your pace. Saved progress stays with your company.')+ownerNav()+A().feedback()+'<section class="panel setup-guide-status"><h2>'+g.completed+' of '+g.total+' setup steps reviewed</h2><p>'+e(g.notice)+'</p><div class="org-status-strip"><div><small>Company</small>'+chip(c.lifecycle)+'</div><div><small>Marketplace review</small>'+chip(c.marketplace_status)+'</div><div><small>Public profile</small><strong>'+(c.storefront_published?'Published':'Unpublished')+'</strong></div></div>'+destination('/distributor/setup?step=review','Review activation & publication')+'</section><ol class="practical-setup-steps">'+g.steps.map(step=>'<li class="panel"><div><h2>'+e(step.title)+'</h2><strong class="setup-guide-state">'+e(states[step.state]||step.state)+'</strong><p>'+e(step.detail)+'</p></div>'+(step.id==='opening'||step.id==='communications'?'':destination(step.url,'Open '+step.title))+'</li>').join('')+'</ol><section class="panel settings-panel"><h2>Bring your existing records</h2><p>Import customers first, then leads for those customers. Review every row before confirming. Existing customers are not overwritten and no login accounts or invitations are created.</p>'+destination('/distributor/import','Review a CSV import')+'<div class="account-actions">'+destination('/distributor/inventory','Review stock records')+destination('/distributor/accounts','Review financial records')+'</div><p class="fine-print">Bulk stock and financial opening-balance import are not available. Use the existing authorized workflows and reconcile source records; the checklist does not post entries.</p></section><section class="panel settings-panel"><h2>Review communications</h2><p>Email configuration: '+(g.communications.emailConfigured?'Available in configuration; delivery not verified here.':'Unavailable. Ask the platform operator to configure email before relying on invitations or recovery.')+'</p><p>Invitation mode: '+e(g.communications.invitationMode)+'. In-app reminders need approved rules and a running worker. Automated WhatsApp and SMS are unavailable.</p><div class="account-actions">'+destination('/distributor/branding','Review public contacts')+destination('/distributor/automation','Review reminder approvals')+'</div><p>Invitations and security emails are separate from optional customer reminders. No message is sent by saving this guide.</p></section><section class="panel settings-panel"><h2>Save your setup decisions</h2><p>These are reviewed choices, not proof of publication, delivery, financial reconciliation or payment.</p><fieldset '+(!g.canManage?'disabled':'')+'>'+orgForm('org-setup-decisions',revision(c)+select('Product offers','offers',[['undecided','Not decided'],['use_offers','I will add product offers'],['not_needed','No product offers needed'],['later','Decide later']],g.choices.offers_mode)+select('Team','team',[['undecided','Not decided'],['invite_team','I will invite employees'],['solo','I am working alone'],['later','Decide later']],g.choices.team_mode)+select('Opening records','opening',[['undecided','Not decided'],['start_fresh','Start with new records'],['reviewed','I reviewed my existing records'],['later','Review later']],g.choices.opening_mode)+checkbox('I reviewed contact and communication settings. This does not enable messaging.','communicationsReviewed',g.choices.communications_reviewed)+field('Reason for these choices','reason','','required minlength="10" maxlength="300"')+'<p class="fine-print">Your choices are recorded in the company audit trail.</p>','Save reviewed choices')+'</fieldset></section>';
  });}
  function setupPage(p){if(params().get('step')==='delivery')return deliveryPage(p);if(params().get('step')==='guide')return practicalSetup(p);return A().resource(p,'/companies/current/setup',d=>{if(!A().session.permissions.includes('company.onboarding.manage'))return readOnlyCompany(d);if(p==='/distributor/dashboard'||p==='/distributor/settings')return summary(d);const step=p==='/distributor/branding'?'brand':params().get('step')||(!d.onboarding.profile_saved_at?'profile':!d.onboarding.brand_saved_at?'brand':!d.onboarding.business_saved_at?'business':'review');const readOnly=['pending_review','suspended'].includes(d.company.lifecycle);return `${heading('SET UP YOUR COMPANY','One clear step at a time.','Your saved progress stays with your company after sign-out and refresh.')}${ownerNav()}${setupProgress(d)}${A().feedback()}${readOnly&&step!=='review'?`<div class="info-callout">${d.company.lifecycle==='suspended'?'This company is suspended.':'Your submission is under review.'} Editing is currently unavailable. ${link('/distributor/setup?step=review','View review status','text-link')}</div>`:''}<div ${readOnly&&step!=='review'?'class="read-only-step"':''}>${readOnly&&step!=='review'?'<fieldset disabled>':''}${step==='brand'?brandStep(d):step==='business'?businessStep(d):step==='review'?reviewStep(d):profileStep(d)}${readOnly&&step!=='review'?'</fieldset>':''}</div>`;});}
  function readOnlyTeam(d){return heading('YOUR PEOPLE, CONNECTED','Company team','Read-only access. Only an authorised company owner can change roles or employee access.')+A().feedback()+'<section class="panel settings-panel"><h2>Company memberships</h2>'+d.members.map(m=>'<article class="purchase-note"><strong>'+e(m.name)+'</strong><p>'+e(A().roleLabel(m.role))+' - '+e(m.status)+'</p><small>'+e(m.email)+'</small></article>').join('')+(A().session.permissions.includes('audit.read')?link('/distributor/audit','View company audit trail','btn secondary'):'')+'</section>';}
  function readOnlyCompany(d){return heading('COMPANY DETAILS',e(d.company.name),'Read-only company profile. Changes require the existing owner permissions.')+Workspace.osOverview(d)+'<section class="panel settings-panel"><h2>Saved company details</h2><p>'+e(d.profile.legal_name||'Legal name not recorded')+'</p><p>'+e(d.profile.address||'Address not recorded')+'</p><p>'+e(d.profile.district||'')+' '+e(d.profile.state||'')+' '+e(d.profile.pin_code||'')+'</p><p>Operating type: '+e(Workspace.presets[d.profile.business_type]?.label||'Not recorded')+'</p><p>Activation: '+e(d.company.lifecycle)+'</p></section>';}
  function companyAudit(){return A().resource('/distributor/audit','/companies/current/audit',d=>heading('COMPANY RECORDS','Audit trail','Read-only history of recorded changes in this company. This screen does not approve or sign off an audit.')+'<section class="panel settings-panel">'+(d.events.length?d.events.map(event=>'<details class="purchase-note"><summary>'+e(event.action)+' - '+e(new Date(event.created_at).toLocaleString())+'</summary><p>Record: '+e(event.target_id||'Not recorded')+'</p><p>Reason: '+e(event.metadata?.reason||'No reason recorded')+'</p><pre class="solar-os-audit-values">'+e(JSON.stringify({previous:event.metadata?.previous??null,next:event.metadata?.next??null},null,2))+'</pre></details>').join(''):'<p>No company changes are recorded yet.</p>')+'</section>');}
  function teamPage(){return A().resource('/distributor/team','/companies/current/team',d=>d.readOnly?readOnlyTeam(d):`${heading('YOUR PEOPLE, CONNECTED','Manage your team.','Company roles stay separate from platform privileges.')}${ownerNav()}${A().feedback()}${peopleControls(d.controls,d.readOnly)}${departureControls(d.controls,d.readOnly)}${Growth.team(d)}${inviteReceipt()}<section class="panel"><div class="panel-heading"><h2>Company memberships</h2></div><div class="member-list">${d.members.map(member=>`<div class="member-row"><div><strong>${e(member.name)}</strong><small>${e(member.email)}</small></div>${member.role==='owner'?status('Owner · Protected','gold'):`<form class="org-member-form" data-member="${e(member.id)}"><fieldset ${d.readOnly?'disabled':''}>${select('Role','role',d.assignableRoles.filter(role=>role==='part_time_sales'?member.role===role:member.role!=='part_time_sales').map(role=>[role,A().roleLabel(role)]),member.role)}${select('Access','status',[['active','Active',member.role==='part_time_sales'&&!d.growth?.enabled],['suspended','Suspended'],['removed','Removed']],member.status)}<p class="org-feedback account-feedback" role="status"></p><button class="btn small secondary">Save access</button></fieldset></form>`}</div>`).join('')}</div><div class="settings-panel"><h3>Invite a person</h3><p class="muted">Share a private link through WhatsApp or your email app. Employees choose their own passwords; invitations expire after 48 hours.</p><fieldset ${d.readOnly?'disabled':''}>${orgForm('org-invite',field('Invitee email','email','','required maxlength="254"','email')+select('Company role','role',d.assignableRoles.filter(role=>role!=='part_time_sales').map(role=>[role,A().roleLabel(role)]),'sales')+invitationProfile(d)+deliveryFields(d.emailAvailable),'Create invitation')}</fieldset><details class="account-space"><summary>Add an existing registered account directly</summary><p class="fine-print">Existing Phase 2 capability. Confirm the person’s registered email before granting access.</p><fieldset ${d.readOnly?'disabled':''}>${A().form('account-member-add',field('Registered email','email','','required maxlength="254"','email')+select('Role','role',d.assignableRoles.filter(role=>role!=='part_time_sales').map(role=>[role,A().roleLabel(role)]),'sales')+invitationProfile(d),'Add membership')}</fieldset></details></div></section><section class="panel account-space"><div class="panel-heading"><h2>Invitations</h2></div><ul class="invitation-list">${d.invitations.map(i=>`<li><div><strong>${e(i.email)}</strong><small>${e(A().roleLabel(i.role))} · ${e(i.status)} · Expires ${e(when(i.expires_at))}</small></div>${i.status==='pending'&&!d.readOnly?`<button class="btn small secondary" data-org-action="revoke-invite" data-id="${i.id}">Revoke invitation</button>`:''}</li>`).join('')||'<li>No invitations yet.</li>'}</ul></section>${history(d.events)}`);}
  function deliveryFields(emailAvailable=A().session.recoveryAvailable){return select('How to share','delivery',[['share','Private link - WhatsApp or email app'],...(emailAvailable?[['email','Send automatic email']]:[])],'share');}
  function invitationProfile(data){const profiles=(data.controls?.profiles||[]).filter(p=>p.active);return `<div data-profile-picker="${e(JSON.stringify(profiles))}">${select('Company role profile','profileId',[['','Standard base role'],...profiles.filter(p=>p.base_role==='sales').map(p=>[p.id,p.name])],'')}</div>`;}
  document.addEventListener('change',event=>{if(!event.target.matches('[name=role]'))return;const box=event.target.form?.querySelector('[data-profile-picker]');if(box)box.innerHTML=select('Company role profile','profileId',[['','Standard base role'],...JSON.parse(box.dataset.profilePicker).filter(p=>p.base_role===event.target.value).map(p=>[p.id,p.name])],'');});
  const retainChoice=(choices,value)=>value&&!choices.some(([id])=>id===value)?[...choices,[value,'Existing inactive assignment ? choose an active replacement']]:choices;
  const controlReason=()=>field('Reason for this change','reason','','required minlength="10" maxlength="300"');
  const controlHidden=(name,value)=>`<input type="hidden" name="${name}" value="${e(value)}">`;
  function controlForm(endpoint,body,label){return `<form class="people-control org-form" data-control="${e(endpoint)}" data-company="${e(A().activeCompany.id)}">${body}${controlReason()}<p class="org-feedback" role="status"></p><button class="btn primary">${label}</button></form>`;}
  function permissionChoices(values,selected){const verbs={read:'View',manage:'Add and update',approve:'Approve',send:'Send',confirm:'Confirm',reverse:'Reverse',own:'My assigned work',progress:'Update progress',assigned:'Assigned records'};return values.map(p=>`<label class="checkbox-label"><input type="checkbox" name="permissions" value="${e(p)}" ${selected.includes(p)?'checked':''}> ${e(p.split('.').map(x=>verbs[x]||x.replaceAll('_',' ')).join(' · '))}</label>`).join('');}
  function pipelineRow(row,stages){return `<fieldset class="sales-stage"><legend>Sales stage</legend>${controlHidden('code',row.code)}${field('Stage name','stageLabel',row.label,'required maxlength="60"')}${select('Sales milestone','category',['new','contacted','qualified','opportunity','won','lost'].map(x=>[x,x]),row.category)}<label>Allowed next stages<select name="next" multiple size="4">${stages.filter(s=>s.code!==row.code).map(s=>`<option value="${e(s.code)}" ${row.next.includes(s.code)?'selected':''}>${e(s.label)}</option>`).join('')}</select></label>${['new','won','lost'].includes(row.code)?'':'<button type="button" class="btn secondary" data-stage-remove>Remove unused stage</button>'}</fieldset>`;}
  function roleTemplateChoices(templates){return '<details class="solar-os-role-templates" open><summary>Start with a job-role template</summary><p>Choose a starting point, review its permissions, save a company role profile, then select that profile in an invitation. Nothing is granted until the owner saves and assigns it.</p><div class="solar-os-template-grid">'+templates.map(template=>'<article><strong>'+e(template.label)+'</strong><p>'+e(template.limitations)+'</p><button type="button" class="btn secondary small" data-role-template="'+e(JSON.stringify(template))+'" '+(!template.available?'disabled':'')+'>'+(template.available?'Review template':'Protected ownership workflow')+'</button></article>').join('')+'</div><p class="fine-print">Branches, payroll and HR records are not represented by these job titles. Teams and reporting managers use the existing company access rules.</p></details>';}
  document.addEventListener('click',event=>{const target=event.target.closest('[data-role-template]');if(!target||target.disabled)return;const template=JSON.parse(target.dataset.roleTemplate);const form=[...document.querySelectorAll('form.people-control[data-control="profiles"]')].find(f=>!f.elements.id.value);if(!form)return;form.elements.name.value=template.label;form.elements.baseRole.value=template.baseRole;const box=form.querySelector('[data-profile-permissions]'),bases=JSON.parse(box.dataset.bases);box.innerHTML=permissionChoices(bases[template.baseRole]||[],template.permissions);form.elements.discountPercent.value='';form.elements.active.checked=true;form.querySelector('.org-feedback').textContent='Template loaded for review. No permissions have been saved or assigned.';for(let parent=form.parentElement;parent;parent=parent.parentElement)if(parent.tagName==='DETAILS')parent.open=true;form.elements.name.focus();});
  function peopleControls(data,readOnly){if(!data?.owner)return '';const active=data.people.filter(p=>p.status==='active'&&(!p.user_status||p.user_status==='active')),members=[['','Not assigned'],...active.map(p=>[p.id,p.name])],policy=data.policy;
   let html=`<section class="panel account-space people-controls"><h2>Teams, responsibilities and sales controls</h2><p>Company role profiles narrow a staff role. Only quotation approval can be separately delegated. Owner and platform access are protected. A reporting manager does not automatically gain access to an employee's records.</p><fieldset ${readOnly?'disabled':''}>`;
   html+='<details><summary>Teams</summary>'+[...data.teams,{}].map(team=>`<details><summary>${e(team.name||'Create a team')}</summary>${controlForm('teams',controlHidden('id',team.id||'')+controlHidden('revision',team.revision||1)+field('Team name','name',team.name||'','required maxlength="80"')+select('Team manager','managerId',retainChoice(members,team.manager_id),team.manager_id||'')+`<label class="checkbox-label"><input type="checkbox" name="active" ${team.active!==false?'checked':''}>Active team</label>`,'Save team')}</details>`).join('')+'</details>';
   html+=roleTemplateChoices(data.templates||[]);
   html+='<details><summary>Company role profiles</summary><p>Inactive profiles keep their history and restrict assigned employees to basic workspace access.</p>'+[...data.profiles,{}].map(profile=>{const base=profile.base_role||'sales',grants=data.bases[base]||[];return `<details><summary>${e(profile.name||'Create a role profile')}</summary>${controlForm('profiles',controlHidden('id',profile.id||'')+controlHidden('revision',profile.revision||1)+field('Role profile name','name',profile.name||'','required maxlength="80"')+select('Base staff role','baseRole',Object.keys(data.bases).map(r=>[r,A().roleLabel(r)]),base)+`<div data-profile-permissions data-bases="${e(JSON.stringify(data.bases))}">${permissionChoices(grants,profile.permissions||grants.filter(p=>p!=='quotations.approve'))}</div>`+field('Maximum discount per line (%) — blank uses company limit','discountPercent',profile.discount_limit_bps==null?'':String(profile.discount_limit_bps/100),'inputmode="decimal"')+`<label class="checkbox-label"><input type="checkbox" name="active" ${profile.active!==false?'checked':''}>Active profile</label>`,'Save role profile')}</details>`;}).join('')+'</details>';
   html+='<details><summary>Assign teams, managers and role profiles</summary>'+data.people.map(person=>`<details><summary>${e(person.name)} · ${e(A().roleLabel(person.role_id))} · ${e(person.status)}</summary>${controlForm('people/'+person.id,controlHidden('revision',person.people_revision)+select('Team','teamId',retainChoice([['','No team'],...data.teams.filter(t=>t.active).map(t=>[t.id,t.name])],person.team_id),person.team_id||'')+select('Reports to','managerId',retainChoice(members.filter(([id])=>id!==person.id),person.reporting_manager_id),person.reporting_manager_id||'')+select('Company role profile','profileId',retainChoice([['','Standard base role'],...data.profiles.filter(p=>p.active&&p.base_role===person.role_id).map(p=>[p.id,p.name])],person.role_profile_id),person.role_profile_id||''),'Save responsibilities')}</details>`).join('')+'</details>';
   html+=`<details><summary>Sales pipeline and quotation approval</summary><p>Discount limits apply to each equipment line, before tax. Above-limit drafts require approval. Changing this policy invalidates pending approvals; issued quotations retain their saved terms.</p>${controlForm('policy',controlHidden('revision',policy.revision)+`<label class="checkbox-label"><input type="checkbox" name="requireReview" ${policy.require_review?'checked':''}>Require review before sending every quotation</label><label class="checkbox-label"><input type="checkbox" name="qualificationRequired" ${policy.qualification_required?'checked':''}>Require customer requirement and site address before qualification</label>`+field('Maximum line discount without approval (%)','discountPercent',String(policy.discount_limit_bps/100),'required inputmode="decimal"')+`<div data-sales-pipeline>${policy.pipeline.map(row=>pipelineRow(row,policy.pipeline)).join('')}</div><button type="button" class="btn secondary" data-stage-add>Add a sales stage</button>`,'Save sales controls')}</details></fieldset></section>`;return html;
  }
  function departureControls(data,readOnly){if(!data?.owner||readOnly)return '';return '<section class="panel account-space"><h2>Employee departure and work handoff</h2><p>Review and transfer outstanding work before suspending or removing an employee. Use an authorised receiving employee; owner access is protected.</p>'+data.people.filter(p=>p.role_id!=='owner').map(p=>'<details><summary>'+e(p.name)+' - '+e(p.status)+'</summary>'+Operations.handoffForm('/companies/current/controls/people/'+p.id+'/departure',select('Access after handoff','status',[['suspended','Suspend access'],['removed','Remove access']],'suspended'))+'</details>').join('')+'</section>';}
  function refreshStageChoices(form){const rows=[...form.querySelectorAll('.sales-stage')],stages=rows.map(r=>({code:r.querySelector('[name=code]').value,label:r.querySelector('[name=stageLabel]').value}));for(const row of rows){const select=row.querySelector('[name=next]'),chosen=[...select.selectedOptions].map(o=>o.value),code=row.querySelector('[name=code]').value;select.innerHTML=stages.filter(s=>s.code!==code).map(s=>`<option value="${e(s.code)}" ${chosen.includes(s.code)?'selected':''}>${e(s.label)}</option>`).join('');}}
  document.addEventListener('change',event=>{if(event.target.matches('.people-control [name=baseRole]')){const node=event.target.form.querySelector('[data-profile-permissions]'),grants=JSON.parse(node.dataset.bases)[event.target.value]||[];node.innerHTML=permissionChoices(grants,grants.filter(p=>p!=='quotations.approve'));}if(event.target.matches('.sales-stage [name=stageLabel]'))refreshStageChoices(event.target.form);});
  document.addEventListener('click',event=>{const add=event.target.closest('[data-stage-add]'),remove=event.target.closest('[data-stage-remove]');if(add){const holder=add.form.querySelector('[data-sales-pipeline]');if(holder.children.length>=20)return;holder.insertAdjacentHTML('beforeend',pipelineRow({code:'step_'+crypto.randomUUID().slice(0,8),label:'New stage',category:'contacted',next:[]},[]));refreshStageChoices(add.form);}if(remove){const f=remove.form;remove.closest('.sales-stage').remove();refreshStageChoices(f);}});
  function setInvitationReceipt(result){
    invitationReceipt=null;const raw=result.shareUrl||result.manualUrl;if(!raw)return;
    try{const u=new URL(raw);if(u.origin!==location.origin||!u.hash.startsWith('#/invitation?')||result.companyId&&result.companyId!==A().session.activeCompany?.id)return;invitationReceipt={...result,shareUrl:u.href};}catch{}
  }
  function inviteReceipt(kind='employee',contactId=null){
    if(!invitationReceipt||(invitationReceipt.kind||'employee')!==kind||contactId&&invitationReceipt.contactId!==contactId)return '';const r=invitationReceipt,message=`You are invited to ${r.companyName||'MY Solar Solutions'}. Open this private link and sign in or create your own account using ${r.recipient||'the invited email'}. It expires in 48 hours. Choose your own password.\n\n${r.shareUrl}`;
    return `<section class="panel invitation-share" aria-label="Share private invitation"><h2>Your private invitation is ready</h2><p>For <strong>${e(r.recipient||'the named recipient')}</strong>. No message has been sent. Share only with this person; the link expires after 48 hours.</p><label>Private invitation link<input id="private-invite-link" readonly value="${e(r.shareUrl)}"></label><div class="account-actions"><a class="btn primary" href="https://wa.me/?text=${e(encodeURIComponent(message))}" target="_blank" rel="noopener noreferrer">${icon('users')}Share on WhatsApp</a><a class="btn secondary" href="mailto:${e(encodeURIComponent(r.recipient||''))}?subject=${encodeURIComponent('Your MY Solar Solutions invitation')}&amp;body=${e(encodeURIComponent(message))}">${icon('file')}Open email app</a><button type="button" class="btn secondary" data-org-action="copy-invite">Copy link</button><button type="button" class="btn secondary" data-org-action="hide-invite">Hide private link</button></div><p class="fine-print">Opening WhatsApp or your email app prepares a message. You review and send it yourself. The link is kept only in this tab's memory; create a new invitation if it is lost.</p></section>`;
  }
  function prepareInvitation(){
    const scope=invitationToken+':'+A().user?.id;if(!A().user||!invitationToken||previewScope===scope)return;
    previewScope=scope;invitationPreview=null;invitationPreviewError='';
    void A().api('/invitations/preview','POST',{token:invitationToken,kind:invitationKind}).then(result=>{if(previewScope===scope){invitationPreview=result;if(path()==='/invitation')render();}}).catch(error=>{if(previewScope===scope){invitationPreviewError=error.message;if(path()==='/invitation')render();}});
  }
  function invitationPage(){prepareInvitation();if(invitationKind==='partner')return Growth.invitation({token:invitationToken,preview:invitationPreview,error:invitationPreviewError});const customer=invitationKind==='customer';return `<section class="panel invitation-accept"><p class="eyebrow">${customer?'YOUR CUSTOMER ACCOUNT':'A PLACE ON THE TEAM'}</p><h1>${customer?'Connect with your solar company.':'Your company invitation.'}</h1><p class="muted">Accept only an invitation you expected. Sign in or register with the invited email address and choose your own password.</p>${!invitationToken?'<p class="account-feedback">Open the private invitation link. Refreshing this page requires reopening the link.</p>':!A().user?`<div class="account-actions">${link('/customer/login','Sign in to accept','btn primary')}${link('/register','Create an account','btn secondary')}</div>`:`<p>Signed in as <strong>${e(A().user.email)}</strong></p>${invitationPreview?'<p>Company: <strong>'+e(invitationPreview.company_name)+'</strong></p><p>Access: '+e(customer?'Customer records':A().roleLabel(invitationPreview.role))+' - Expires '+when(invitationPreview.expires_at)+'</p>':''}${invitationPreview?orgForm('org-accept-invite',customer?'<label class="checkbox-label"><input type="checkbox" name="confirmAccess" required> Connect my account to this company&#39;s existing and future customer-visible orders, installation updates, invoices and service requests.</label><p class="fine-print">This does not accept an order, confirm a payment or give access to company staff tools.</p>':'','Accept invitation'):invitationPreviewError?'<p class="account-feedback" role="alert">'+e(invitationPreviewError)+'</p><button type="button" class="btn secondary" data-org-action="retry-invitation">Try again</button>':'<p role="status">Checking your private invitation...</p>'}`}${A().feedback()}</section>`;}
  function platformNav(){return `<nav class="org-subnav platform-subnav" aria-label="Platform administration">${link('/platform','Company directory')}${link('/platform?queue=onboarding','Onboarding reviews')}${link('/platform?queue=marketplace','Marketplace reviews')}${link('/platform/settings','Commercial controls')}${link('/platform/audit','Platform activity')}</nav>`;}
  function platformDirectory(){const q=params();const query=new URLSearchParams();for(const key of ['search','lifecycle','marketplace','queue','page'])if(q.get(key))query.set(key,q.get(key));return A().resource('/platform',`/platform/companies?${query}`,d=>`${heading('PLATFORM ADMINISTRATION','Company directory','Authorized company review. No customer or financial records are shown.')}${platformNav()}${A().feedback()}<section class="panel admin-directory"><form id="org-directory" class="admin-search">${field('Search company or district','search',q.get('search')||'','maxlength="100"')}${select('Lifecycle','lifecycle',[['','All states'],...['draft','onboarding','pending_review','active','suspended'].map(value=>[value,labels[value]])],q.get('lifecycle')||'')}${select('Marketplace','marketplace',[['','All states'],...['not_requested','pending','approved','rejected','withdrawn'].map(value=>[value,labels[value]])],q.get('marketplace')||'')}<input type="hidden" name="queue" value="${e(q.get('queue')||'')}"><button class="btn primary">Search</button></form><div class="table-scroll"><table><caption class="sr-only">Authorized distributor company directory</caption><thead><tr><th>Company</th><th>Location</th><th>Activation</th><th>Marketplace</th><th>Review</th></tr></thead><tbody>${d.companies.map(c=>`<tr><td><strong>${e(c.name)}</strong></td><td>${e(c.city)}</td><td>${chip(c.lifecycle)}</td><td>${chip(c.marketplace_status)}</td><td>${link(`/platform/company?id=${c.id}`,'Review company '+icon('chevron'),'text-link')}</td></tr>`).join('')}</tbody></table></div>${d.companies.length?'':'<p class="empty-inline">No companies match these filters.</p>'}<div class="table-foot"><span>${d.total} companies · Page ${d.page}</span><div>${d.page>1?`<button class="btn small secondary" data-org-action="page" data-page="${d.page-1}">Previous</button>`:''}${d.page*d.pageSize<d.total?`<button class="btn small secondary" data-org-action="page" data-page="${d.page+1}">Next</button>`:''}</div></div></section>`);}
  function platformCompany(){const id=params().get('id')||'';return A().resource('/platform/company',`/platform/companies/${encodeURIComponent(id)}`,d=>{const c=d.company;const allowed=[];const p=A().session.platformPermissions||[];
    if(c.lifecycle==='pending_review'&&p.includes('platform.onboarding.review'))allowed.push(['approve','Approve activation'],['reject','Request onboarding changes']);
    if(p.includes('platform.lifecycle.manage'))allowed.push(c.lifecycle==='suspended'?['reactivate','Reactivate to previous state']:['suspend','Suspend company']);
    if(p.includes('platform.marketplace.review')){if(c.marketplace_status==='pending'){if(c.lifecycle==='active')allowed.push(['approve_marketplace','Approve marketplace application']);allowed.push(['reject_marketplace','Reject marketplace application']);}if(c.lifecycle==='active'&&c.marketplace_status==='approved'&&!c.storefront_published)allowed.push(['publish','Publish approved storefront']);if(c.storefront_published)allowed.push(['unpublish','Unpublish storefront']);}
    return `${heading('PLATFORM COMPANY REVIEW',e(c.name),'Activation, marketplace approval and publication are separate decisions.')}${platformNav()}${A().feedback()}<div class="org-status-strip"><div><small>Activation</small>${chip(c.lifecycle)}</div><div><small>Marketplace</small>${chip(c.marketplace_status)}</div><div><small>Publication</small>${status(c.storefront_published?'Published':'Unpublished')}</div></div><div class="admin-review-grid"><section class="panel review-summary"><h2>Submitted company information</h2><dl><dt>Legal name / business type</dt><dd>${e(d.profile.legal_name)} · ${e(Workspace.presets[d.profile.business_preset||d.profile.business_type]?.label||d.profile.business_type)}</dd><dt>Primary contact</dt><dd>${e(d.profile.primary_contact)}</dd><dt>Business contact</dt><dd>${e(c.business_email)} · ${e(c.phone)}</dd><dt>Business address</dt><dd>${e(d.profile.address)}, ${e(d.profile.district)}, ${e(d.profile.state)} ${e(d.profile.pin_code)}</dd><dt>Website</dt><dd>${e(d.profile.website)||'Not provided'}</dd><dt>Services and areas</dt><dd>${d.business.services.map(value=>e(serviceLabels[value]||value)).join(', ')}<br>${e(d.business.service_areas.join(', '))}</dd><dt>Setup steps saved</dt><dd>${[d.onboarding.profile_saved_at,d.onboarding.brand_saved_at,d.onboarding.business_saved_at].filter(Boolean).length} of 3</dd><dt>Active team memberships</dt><dd>${d.members.active}</dd></dl><p class="muted">Review the information supplied; approval does not assert independent business verification.</p></section><div>${brandPreview(d.brand)}<section class="panel settings-panel account-space"><h2>Record a review decision</h2>${allowed.length?orgForm('org-review',`<input type="hidden" name="companyId" value="${c.id}">`+revision(c)+select('Decision','action',allowed,allowed[0][0])+textarea('Reason · required for rejection or suspension','reason','','maxlength="500"')+'<p class="fine-print">Rejection and suspension need at least 10 characters. Every decision records your identity, previous/new state, revision, reason and timestamp.</p>','Save decision'):'<p class="muted">No review actions are available with your current permissions.</p>'}</section></div></div>${history(d.history)}${history(d.activity)}`;
  });}
  function platformSettings(){return A().resource('/platform/settings','/platform/settings',({settings:s})=>`${heading('PLATFORM COMMERCIAL FOUNDATION','Proposed settings. No charges.','These settings do not activate billing, trials or feature enforcement.')}${platformNav()}<section class="panel settings-panel"><h2>White-label reference settings</h2><p class="info-callout">Billing is disabled. The initial setup reference is ₹35,000 plus GST.</p><fieldset ${(A().session.platformPermissions||[]).includes('platform.settings.manage')?'':'disabled'}>${orgForm('org-commercial',revision(s)+field('Proposed one-time setup fee · INR','setupFee',Number(s.proposed_setup_fee_paise)/100,'required min="0" max="10000000" step="0.01"','number')+field('GST / reference note','gstNote',s.gst_note,'required maxlength="300"')+field('Proposed monthly subscription · optional INR','subscription',s.proposed_subscription_paise===null?'':Number(s.proposed_subscription_paise)/100,'min="0" max="10000000" step="0.01"','number')+field('Proposed trial days · optional','trial',s.proposed_trial_days??'','min="0" max="365" step="1"','number')+field('Future team limit · optional','team',s.future_limits.team??'','min="1" max="1000000"','number')+field('Future product limit · optional','products',s.future_limits.products??'','min="1" max="1000000"','number')+field('Future project limit · optional','projects',s.future_limits.projects??'','min="1" max="1000000"','number'),'Save proposed settings')}</fieldset></section>`);}
  function publicStorefront(){const id=params().get('company')||'';return A().resource('/storefront',`/public/vendors/${encodeURIComponent(id)}`,({vendor:b})=>`${heading('ON THE MY SOLAR PLATFORM',e(b.name),'Published distributor information. No products, price offers or availability are listed.')}<div class="public-storefront" style="--preview-primary:${e(b.primary_color)};--preview-secondary:${e(b.secondary_color)};--preview-accent:${e(b.accent_color)}">${brandPreview({...b,public_name:b.name})}<section class="panel review-summary"><h2>Solutions and service areas</h2><p>${b.services.map(value=>e(serviceLabels[value]||value)).join(', ')}</p><p class="muted">${e(b.service_areas.join(', '))}</p><h3>Contact this company</h3>${b.public_email?`<p>${e(b.public_email)}</p>`:''}${b.public_phone?`<p>${e(b.public_phone)}</p>`:''}<p class="fine-print">Publication approval is not a business-verification claim. MY SOLAR’s marketplace identity remains separate from this company.</p><button class="btn secondary" disabled>Quotation enquiries · Later phase</button></section></div>`);}
  function page(p){
    if(p.startsWith('/platform')){const marketplacePage=Marketplace.page(p);if(marketplacePage!==null)return marketplacePage;}
    if(p==='/storefront')return publicStorefront();if(p==='/invitation')return invitationPage();
    if(p.startsWith('/platform')){if(!(A().session.platformPermissions||[]).includes(p==='/platform/settings'?'platform.settings.read':p==='/platform/audit'?'platform.audit.read':'platform.companies.read'))return `<section class="panel account-state"><h2>Platform operator access required.</h2><p class="muted">Privileges are issued through the server-controlled operator procedure. Company ownership does not grant platform access.</p></section>`;if(p==='/platform/company')return platformCompany();if(p==='/platform/settings')return platformSettings();if(p==='/platform/audit')return A().resource(p,'/platform/audit',d=>`${heading('PLATFORM ADMINISTRATION','Platform activity','Significant operator and account security events.')}${platformNav()}${history(d.events)}`);return platformDirectory();}
    if(['/distributor/public-profile','/distributor/white-label'].includes(p))return facilityPage(p);
    if(p==='/distributor/partners')return Growth.page(p);
    if(p==='/distributor/team')return teamPage();
    if(p==='/distributor/audit')return companyAudit();
    if(['/distributor/setup','/distributor/branding','/distributor/settings'].includes(p)||(p==='/distributor/dashboard'&&A().session.permissions.includes('company.setup.read')))return setupPage(p);
    return null;
  }
  function updatePreview(form){const preview=document.getElementById('brand-live-preview');if(!preview)return;const d=Object.fromEntries(new FormData(form));for(const [key,selector] of [['publicName','preview-name'],['welcome','preview-welcome'],['description','preview-description'],['email','preview-email'],['phone','preview-phone']])document.getElementById(selector).textContent=d[key]||'';for(const key of ['primary','secondary','accent'])if(/^#[0-9a-f]{6}$/i.test(d[key]))preview.style.setProperty(`--preview-${key}`,d[key]);preview.classList.toggle('clean',d.appearance==='clean');let safe='';try{const u=new URL(d.logoUrl);if(u.protocol==='https:'&&!u.username&&!u.password&&!u.port&&logoHosts.includes(u.hostname)&&/\.(png|jpe?g|webp)$/i.test(u.pathname)&&!u.search&&!u.hash)safe=u.href;}catch{}document.getElementById('preview-logo').innerHTML=logo(safe);}
  async function changed(result,next){await A().refresh();A().setMessage(result.message||'Saved.');if(next)A().navigate(next);else render();}
  document.addEventListener('error',event=>{if(event.target instanceof HTMLImageElement&&event.target.classList.contains('tenant-logo'))event.target.remove();},true);
  document.addEventListener('input',event=>{const f=event.target.closest('#org-brand');if(f)updatePreview(f);});
  document.addEventListener('change',event=>{const f=event.target.closest('#org-brand');if(f)updatePreview(f);});
  function perform(action,form){void A().run(async()=>{try{await action();}catch(error){form?.querySelectorAll('details').forEach(item=>item.open=true);const target=form?.querySelector('.org-feedback')||document.querySelector('.org-feedback');if(target)target.textContent=error.message;else{A().setMessage(error.message);render();}throw error;}},form);}
  document.addEventListener('submit',event=>{
    const f=event.target;if(!f.matches('.org-form,.org-member-form,#org-directory'))return;event.preventDefault();const d=Object.fromEntries(new FormData(f));
    perform(async()=>{
      if(f.id==='org-directory'){const q=new URLSearchParams();for(const [key,value] of Object.entries(d))if(value)q.set(key,value);A().navigate(`/platform?${q}`);return;}
      if(d.revision)d.revision=Number(d.revision);
      if(f.classList.contains('people-control')){if(f.dataset.company!==A().activeCompany?.id)throw new Error('Your active company changed. Refresh before saving.');const endpoint=f.dataset.control;delete d.reason;const payload={...Object.fromEntries(new FormData(f)),revision:Number(f.elements.revision?.value||1)};if(endpoint==='teams')payload.active=f.elements.active.checked;if(endpoint==='profiles'||endpoint==='policy'){const value=f.elements.discountPercent.value;if(value!==''&&!/^\d{1,3}(?:\.\d{1,2})?$/.test(value))throw new Error('Enter a percentage from 0 to 100 with up to two decimal places.');payload.discountLimitBps=value===''?null:Math.round(Number(value)*100);delete payload.discountPercent;}if(endpoint==='profiles'){payload.permissions=new FormData(f).getAll('permissions');payload.active=f.elements.active.checked;}if(endpoint==='policy'){payload.requireReview=f.elements.requireReview.checked;payload.qualificationRequired=f.elements.qualificationRequired.checked;payload.pipeline=[...f.querySelectorAll('.sales-stage')].map(row=>({code:row.querySelector('[name=code]').value,label:row.querySelector('[name=stageLabel]').value,category:row.querySelector('[name=category]').value,next:[...row.querySelector('[name=next]').selectedOptions].map(o=>o.value)}));for(const key of ['code','stageLabel','category','next'])delete payload[key];}if(endpoint.startsWith('people/')){delete payload.id;}await changed(await A().api('/companies/current/controls/'+endpoint,'POST',payload));}
      else if(f.id==='org-setup-decisions'){d.communicationsReviewed=f.elements.communicationsReviewed.checked;await changed(await A().api('/companies/current/setup/decisions','PUT',d),'/distributor/setup?step=guide');}
      else if(f.id==='org-profile'){Object.assign(d,CompanyLocation.values(f));delete d.districtOther;d.businessPreset=Workspace.selectedPreset(f);d.businessType=Workspace.selectedBusinessType(f);delete d.businessTypes;await changed(await A().api('/companies/current/onboarding/profile','PUT',d),'/distributor/setup?step=brand');}
      else if(f.id==='org-brand'){delete d.defaultName;await changed(await A().api('/companies/current/branding','PUT',d),'/distributor/setup?step=business');}
      else if(f.id==='org-business'){d.services=new FormData(f).getAll('services');d.rooftop=f.elements.rooftop.checked;d.marketplaceRequested=f.elements.marketplaceRequested.checked;d.areas=d.areas.split(/\r?\n/).map(value=>value.trim()).filter(Boolean);await changed(await A().api('/companies/current/onboarding/business','PUT',d),'/distributor/setup?step=review');}
      else if(f.id==='org-invite'){const result=await A().api('/companies/current/invitations','POST',d);setInvitationReceipt(result);await changed(result);}
      else if(f.id==='org-accept-invite'){const result=await A().api(invitationKind==='partner'?'/companies/current/partners/accept':invitationKind==='customer'?'/invitations/customer/accept':'/invitations/accept','POST',{token:invitationToken,...(['customer','partner'].includes(invitationKind)?{confirmAccess:f.elements.confirmAccess.checked}:{})});const next=invitationKind==='customer'?'/customer/dashboard':'/distributor/dashboard';invitationToken='';await changed(result,next);}
      else if(f.classList.contains('org-member-form'))await changed(await A().api(`/companies/current/members/${encodeURIComponent(f.dataset.member)}`,'PATCH',d));
      else if(f.id==='org-review'){const id=d.companyId;delete d.companyId;await changed(await A().api(`/platform/companies/${encodeURIComponent(id)}/actions`,'POST',d));}
      else if(f.id==='org-commercial'){const limits={};for(const key of ['team','products','projects'])if(d[key]!=='')limits[key]=Number(d[key]);await changed(await A().api('/platform/settings','PATCH',{revision:d.revision,setupFeePaise:Math.round(Number(d.setupFee)*100),gstNote:d.gstNote,subscriptionPaise:d.subscription===''?null:Math.round(Number(d.subscription)*100),trialDays:d.trial===''?null:Number(d.trial),limits}));}
    },f);
  });
  document.addEventListener('click',event=>{
    const target=event.target.closest('[data-org-action]');if(!target)return;
    if(target.dataset.orgAction==='reset-brand'){const f=document.getElementById('org-brand');const values={publicName:f.elements.defaultName.value,logoUrl:'',primary:defaults.primary,secondary:defaults.secondary,accent:defaults.accent,welcome:defaults.welcome,email:'',phone:'',description:defaults.description,appearance:defaults.appearance,requestedDomain:''};for(const [key,value] of Object.entries(values))f.elements[key].value=value;updatePreview(f);f.querySelector('.org-feedback').textContent='Defaults previewed. Save to apply them to this company.';return;}
    perform(async()=>{const rev=Number(target.dataset.revision);switch(target.dataset.orgAction){case 'submit':await changed(await A().api('/companies/current/onboarding/submit','POST',{revision:rev}));break;case 'withdraw':await changed(await A().api('/companies/current/onboarding/withdraw','POST',{revision:rev}));break;case 'market-request':case 'market-withdraw':await changed(await A().api('/companies/current/marketplace-request','POST',{revision:rev,requested:target.dataset.orgAction==='market-request'}));break;case 'revoke-invite':await changed(await A().api(`/companies/current/invitations/${encodeURIComponent(target.dataset.id)}/revoke`,'POST',{}));break;case 'retry-invitation':previewScope='';render();break;case 'hide-invite':invitationReceipt=null;render();break;case 'copy-invite':if(invitationReceipt){try{await navigator.clipboard.writeText(invitationReceipt.shareUrl);announce('Private link copied. Share only with the named recipient.');}catch{const input=document.getElementById('private-invite-link');input?.focus();input?.select();announce('Select and copy the private link.');}}break;case 'page':{const q=params();q.set('page',target.dataset.page);A().navigate(`/platform?${q}`);break;}}});
  });
  return {page,logo,inviteReceipt,setInvitationReceipt,deliveryFields,registrationAccountType:()=>invitationKind==='employee'?'business':'customer',registrationToken:()=>['employee','customer'].includes(invitationKind)?invitationToken:'',hasInvitation:()=>Boolean(invitationToken),clearSensitive(){invitationReceipt=null;invitationToken='';invitationPreview=null;previewScope='';},
    sessionChanged(previous,next){if(previous.user?.id!==next.user?.id||previous.activeCompany?.id!==next.activeCompany?.id)invitationReceipt=null;if(previous.user?.id!==next.user?.id){invitationPreview=null;previewScope='';}if(previous.user&&!next.user)invitationToken='';}};
})();
